/** @jsxImportSource @opentui/solid */
import type { InputRenderable, KeyEvent } from "@opentui/core"
import { useKeyboard, type JSX } from "@opentui/solid"
import fuzzysort from "fuzzysort"
import { createEffect, createMemo, createSignal, type Accessor } from "solid-js"
import { $ } from "bun"
import { RunFooterMenu, createFooterMenuState, type RunFooterMenuItem } from "./footer.menu"
import type { RunFooterTheme } from "./theme"
import type { RunProvider } from "./types"

type PanelEntry = RunFooterMenuItem & {
  category: string
  keywords?: string
}

type AccountEntry = PanelEntry & {
  providerID: string
}

type ConfirmEntry = PanelEntry & {
  confirm: boolean
  providerID: string
}

type MenuState = ReturnType<typeof createFooterMenuState>

const PANEL_PAD = 2
const PANEL_LIST_ROWS = 10
const PANEL_PAGE = PANEL_LIST_ROWS - 1

// Accounts the user added themselves. Built-ins (openai, auth.json ghosts)
// are never removable.
const REMOVABLE = (id: string) => id.startsWith("meta-") || id === "nvidia-nim"

function handleKey(input: {
  event: KeyEvent
  menu: MenuState
  field: () => InputRenderable | undefined
  setQuery: (value: string) => void
  select: () => void
  close: () => void
}) {
  const name = input.event.name.toLowerCase()
  const ctrl = input.event.ctrl && !input.event.meta && !input.event.shift && !input.event.super

  if (name === "escape" || (ctrl && name === "c")) {
    input.event.preventDefault()
    input.close()
    return
  }

  if (name === "up" || (ctrl && name === "p")) {
    input.event.preventDefault()
    input.menu.move(-1)
    return
  }

  if (name === "down" || (ctrl && name === "n")) {
    input.event.preventDefault()
    input.menu.move(1)
    return
  }

  if (name === "pageup") {
    input.event.preventDefault()
    input.menu.move(-PANEL_PAGE)
    return
  }

  if (name === "pagedown") {
    input.event.preventDefault()
    input.menu.move(PANEL_PAGE)
    return
  }

  if (name === "return" || name === "enter") {
    input.event.preventDefault()
    input.select()
    return
  }
}

function PanelShell(props: {
  title: string
  query: string
  count: number
  total: number
  placeholder: string
  theme: Accessor<RunFooterTheme>
  inputRef: (input: InputRenderable) => void
  onQuery: (query: string) => void
  children: JSX.Element
}) {
  const background = () => props.theme().surface
  return (
    <box flexDirection="column" width="100%" backgroundColor={background()}>
      <box height={1} flexShrink={0} backgroundColor={background()} />
      <box width="100%" height={1} paddingLeft={PANEL_PAD} paddingRight={PANEL_PAD} flexDirection="row" gap={1}>
        <text fg={props.theme().textMuted}>{props.title}</text>
        <text fg={props.theme().textMuted}>
          {props.count}/{props.total}
        </text>
      </box>
      <box width="100%" height={1} paddingLeft={PANEL_PAD} paddingRight={PANEL_PAD}>
        <input
          ref={props.inputRef}
          placeholder={props.placeholder}
          value={props.query}
          onInput={(value) => props.onQuery(value)}
        />
      </box>
      {props.children}
    </box>
  )
}

// Native two-step account removal. Step 1 picks the account, step 2 confirms
// ("Yes, remove X" / "Cancel"). Removal itself shells out to the remove-account
// backend so config + fish key handling stays in one place. No prompt template,
// no AI mediation — nothing printable to echo.
export function RunRemoveAccountBody(props: {
  theme: Accessor<RunFooterTheme>
  providers: Accessor<RunProvider[] | undefined>
  onClose: () => void
  onRemoved: (providerID: string) => void
}) {
  let field: InputRenderable | undefined
  const [query, setQuery] = createSignal("")
  const [chosen, setChosen] = createSignal<string | undefined>(undefined)
  const [removing, setRemoving] = createSignal(false)
  const [error, setError] = createSignal<string | undefined>(undefined)

  const accounts = createMemo<AccountEntry[]>(() =>
    (props.providers() ?? [])
      .filter((provider) => REMOVABLE(provider.id))
      .map((provider) => {
        const count = Object.keys(provider.models ?? {}).length
        return {
          providerID: provider.id,
          category: provider.name ?? provider.id,
          display: provider.id,
          description: `${count} models`,
          footer: provider.id,
          keywords: `${provider.id} ${provider.name ?? ""}`,
        }
      })
      .sort((a, b) => a.providerID.localeCompare(b.providerID)),
  )

  const confirms = createMemo<ConfirmEntry[]>(() => {
    const id = chosen()
    if (!id) return []
    return [
      {
        confirm: true,
        providerID: id,
        category: "",
        display: `Yes, remove ${id}`,
        keywords: `yes remove ${id}`,
      },
      {
        confirm: false,
        providerID: id,
        category: "",
        display: "Cancel",
        keywords: "cancel no",
      },
    ]
  })

  const accountItems = createMemo(() => match(query(), accounts()))
  const confirmItems = createMemo(() => match(query(), confirms()))
  const accountMenu = createFooterMenuState({ count: () => accountItems().length, limit: PANEL_LIST_ROWS })
  const confirmMenu = createFooterMenuState({ count: () => confirmItems().length, limit: PANEL_LIST_ROWS })

  const pickAccount = (item: AccountEntry) => {
    setChosen(item.providerID)
    setQuery("")
    setError(undefined)
  }

  const pickConfirm = async (item: ConfirmEntry) => {
    if (!item.confirm) {
      props.onClose()
      return
    }
    setRemoving(true)
    try {
      const result = await $`${process.env.HOME}/.config/opencode/bin/remove-account --remove ${item.providerID}`
        .quiet()
        .nothrow()
      if (result.exitCode !== 0) {
        setError(result.stderr.toString().trim() || `removal failed (exit ${result.exitCode})`)
        setRemoving(false)
        return
      }
      props.onRemoved(item.providerID)
      props.onClose()
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
      setRemoving(false)
    }
  }

  const select = () => {
    if (removing()) return
    if (chosen() === undefined) {
      const item = accountItems()[accountMenu.selected()]
      if (item) pickAccount(item)
      return
    }
    const item = confirmItems()[confirmMenu.selected()]
    if (item) void pickConfirm(item)
  }

  createEffect(() => {
    query()
    accountMenu.reset()
    confirmMenu.reset()
  })

  useKeyboard((event) => {
    if (event.defaultPrevented) return
    if (chosen() !== undefined && (event.name === "left" || event.name === "backspace")) {
      // Let backspace edit the query when there is one, else go back.
      if (query().length === 0) {
        event.preventDefault()
        setChosen(undefined)
        setError(undefined)
        return
      }
    }
    handleKey({
      event,
      menu: chosen() === undefined ? accountMenu : confirmMenu,
      field: () => field,
      setQuery,
      select,
      close: props.onClose,
    })
  })

  const title = () =>
    removing()
      ? `Removing ${chosen()}…`
      : chosen() === undefined
        ? "Remove account"
        : `Remove ${chosen()}?`
  const items = () => (chosen() === undefined ? accountItems() : confirmItems())

  return (
    <PanelShell
      title={title()}
      query={query()}
      count={items().length}
      total={chosen() === undefined ? accounts().length : confirms().length}
      placeholder={chosen() === undefined ? "Search accounts" : "Confirm"}
      theme={props.theme}
      inputRef={(input) => {
        field = input
      }}
      onQuery={setQuery}
    >
      <RunFooterMenu
        theme={props.theme}
        items={items}
        selected={chosen() === undefined ? accountMenu.selected : confirmMenu.selected}
        offset={chosen() === undefined ? accountMenu.offset : confirmMenu.offset}
        rows={() => PANEL_LIST_ROWS}
        limit={PANEL_LIST_ROWS}
        empty={chosen() === undefined ? "No removable accounts" : "No match"}
        border={false}
        paddingLeft={PANEL_PAD}
        paddingRight={PANEL_PAD}
        grouped={false}
        background
      />
      {error() ? <text fg={props.theme().error}>{error()}</text> : <></>}
    </PanelShell>
  )
}

