import { DialogSelect } from "../ui/dialog-select"
import { DialogConfirm } from "../ui/dialog-confirm"
import { useDialog } from "../ui/dialog"
import { useToast } from "../../ui/toast"
import { useSync } from "../context/sync"
import { $ } from "bun"

// Accounts the user added themselves. Built-ins (openai, auth.json ghosts)
// are never removable.
const REMOVABLE = (id: string) => id.startsWith("meta-") || id === "nvidia-nim"

export function DialogRemoveAccount() {
  const dialog = useDialog()
  const toast = useToast()
  const sync = useSync()

  const accounts = () =>
    (sync.data.provider ?? [])
      .filter((provider) => REMOVABLE(provider.id))
      .map((provider) => ({
        title: provider.id,
        value: provider.id,
        description: `${Object.keys(provider.models ?? {}).length} models`,
      }))
      .sort((a, b) => a.title.localeCompare(b.title))

  const remove = async (providerID: string) => {
    try {
      const result = await $`${process.env.HOME}/.config/opencode/bin/remove-account --remove ${providerID}`
        .quiet()
        .nothrow()
      if (result.exitCode !== 0) {
        const err = result.stderr.toString().trim() || `removal failed (exit ${result.exitCode})`
        toast.show({ message: err, variant: "error" })
        dialog.clear()
        return
      }
      toast.show({ message: `Removed ${providerID}`, variant: "success" })
    } catch (e) {
      toast.show({ message: e instanceof Error ? e.message : String(e), variant: "error" })
    }
    dialog.clear()
  }

  const confirm = async (providerID: string, count: string) => {
    const ok = await DialogConfirm.show(
      dialog,
      "Remove account",
      `Remove ${providerID} (${count})? Deletes its opencode.json block and erases its fish key variable.`,
      `Yes, remove ${providerID}`,
    )
    if (ok === true) await remove(providerID)
    else dialog.clear()
  }

  return (
    <DialogSelect
      title="Remove account"
      options={accounts()}
      emptyView="No removable accounts"
      onSelect={(opt) => {
        void confirm(opt.value, opt.description ?? "")
      }}
    />
  )
}

