import { TextAttributes } from "@opentui/core"
import { useTheme } from "../context/theme"
import { useDialog, type DialogContext } from "./dialog"
import { createStore } from "solid-js/store"
import { For } from "solid-js"
import { Locale } from "../util/locale"
import { useBindings } from "../keymap"

export type DialogConfirmProps = {
  title: string
  message: string
  onConfirm?: () => void
  onCancel?: () => void
  label?: string
}

export type DialogConfirmResult = boolean | undefined

export function DialogConfirm(props: DialogConfirmProps) {
  const dialog = useDialog()
  const { theme } = useTheme()
  const [store, setStore] = createStore({
    active: "confirm" as "confirm" | "cancel",
  })

  useBindings(() => ({
    bindings: [
      {
        key: "return",
        desc: "Confirm dialog selection",
        group: "Dialog",
        cmd: () => {
          if (store.active === "confirm") props.onConfirm?.()
          if (store.active === "cancel") props.onCancel?.()
          dialog.clear()
        },
      },
      {
        key: "left",
        desc: "Previous dialog option",
        group: "Dialog",
        cmd: () => {
          setStore("active", store.active === "confirm" ? "cancel" : "confirm")
        },
      },
      {
        key: "right",
        desc: "Next dialog option",
        group: "Dialog",
        cmd: () => {
          setStore("active", store.active === "confirm" ? "cancel" : "confirm")
        },
      },
    ],
  }))
  return (
    <box paddingLeft={2} paddingRight={2} gap={1}>
      <box flexDirection="row" justifyContent="space-between">
        <text attributes={TextAttributes.BOLD} fg={theme.text}>
          {props.title}
        </text>
        <text fg={theme.textMuted} onMouseUp={() => dialog.clear()}>
          esc
        </text>
      </box>
      <box paddingBottom={1}>
        <text fg={theme.textMuted}>{props.message}</text>
      </box>
      <box flexDirection="row" justifyContent="flex-end" paddingBottom={1}>
        <For each={["cancel", "confirm"] as const}>
          {(key) => (
            <box
              paddingLeft={1}
              paddingRight={1}
              backgroundColor={key === store.active ? theme.primary : undefined}
              onMouseUp={() => {
                if (key === "confirm") props.onConfirm?.()
                if (key === "cancel") props.onCancel?.()
                dialog.clear()
              }}
            >
              <text fg={key === store.active ? theme.selectedListItemText : theme.textMuted}>
                {Locale.titlecase(key === "cancel" ? (props.label ?? key) : key)}
              </text>
            </box>
          )}
        </For>
      </box>
    </box>
  )
}

DialogConfirm.show = (dialog: DialogContext, title: string, message: string, label?: string) => {
  return new Promise<DialogConfirmResult>((resolve) => {
    dialog.replace(
      () => (
        <DialogConfirm
          title={title}
          message={message}
          onConfirm={() => resolve(true)}
          onCancel={() => resolve(false)}
          label={label}
        />
      ),
      () => resolve(undefined),
    )
  })
}

import { DialogSelect } from "../ui/dialog-select"
import { DialogConfirm } from "../ui/dialog-confirm"
import { useDialog } from "../ui/dialog"
import { useToast } from "../ui/toast"
import { useSync } from "../context/sync"
import { $ } from "bun"

// Accounts the user added themselves. Built-ins (openai, auth.json ghosts)
// are never removable.
const REMOVABLE = (id: string) => id.startsWith("meta-") || id === "nvidia-nim"

export function DialogRemoveAccount() {
  const dialog = useDialog()
  const toast = useToast()
  const sync = useSync()

  const accounts = () =>
    (sync.data.provider ?? [])
      .filter((provider) => REMOVABLE(provider.id))
      .map((provider) => ({
        title: provider.id,
        value: provider.id,
        description: `${Object.keys(provider.models ?? {}).length} models`,
      }))
      .sort((a, b) => a.title.localeCompare(b.title))

  const remove = async (providerID: string) => {
    try {
      const result = await $`${process.env.HOME}/.config/opencode/bin/remove-account --remove ${providerID}`
        .quiet()
        .nothrow()
      if (result.exitCode !== 0) {
        const err = result.stderr.toString().trim() || `removal failed (exit ${result.exitCode})`
        toast.show({ message: err, variant: "error" })
        dialog.clear()
        return
      }
      toast.show({ message: `Removed ${providerID}`, variant: "success" })
    } catch (e) {
      toast.show({ message: e instanceof Error ? e.message : String(e), variant: "error" })
    }
    dialog.clear()
  }

  const confirm = async (providerID: string, count: string) => {
    const ok = await DialogConfirm.show(
      dialog,
      "Remove account",
      `Remove ${providerID} (${count})? Deletes its opencode.json block and erases its fish key variable.`,
      `Yes, remove ${providerID}`,
    )
    if (ok === true) await remove(providerID)
    else dialog.clear()
  }

  return (
    <DialogSelect
      title="Remove account"
      options={accounts()}
      emptyView={<text>No removable accounts</text>}
      onSelect={(opt) => {
        void confirm(opt.value, opt.description ?? "")
      }}
    />
  )
}

